import { CACHE_PROFILES, orgTag, projectTag, revalidateTagged } from "@/lib/cache";
import { can } from "@/lib/permissions";
import { createProjectSchema, type CreateProjectInput } from "@/schemas/project";
import { getOrganizationSummary } from "@/server/services/organization-service";
import { createProject } from "@/server/services/project-service";
import type { ActionResult } from "@/types/api";
import type { Project } from "@/types/project";

const run = withAction<typeof createProjectSchema, Project>(
  createProjectSchema,
  async (raw, actor) => {
    const input = raw as CreateProjectInput;

    const allowed = can(actor, "project:create", {
      kind: "project",
      orgId: input.orgId,
      projectId: PENDING_PROJECT_ID,
      visibility: input.visibility,
      leadId: input.leadId,
    });
    if (!allowed) {
      throw new ForbiddenActionError("project:create");
    }

    const summary = await getOrganizationSummary(actor, input.orgId);
    const limits = getPlanLimits(summary.organization.plan);
    if (summary.usage.projectsUsed >= limits.projects) {
      throw new PlanLimitError("projects", limits.projects, summary.usage.projectsUsed);
    }

    const project = await createProject(actor, input);
    revalidateTagged(
      [orgTag(input.orgId), projectTag(project.id)],
      CACHE_PROFILES.minutes,
    );
    return project;
  },
  { revalidate: ["projects"], cacheProfile: "minutes" },
);

export async function createProjectAction(raw: unknown): Promise<ActionResult<Project>> {
  return run(raw);
}
"use server";

/**
 * Restores an archived project.
 *
 * Owner D. There is no `restoreProjectSchema` in `src/schemas` because the
 * payload is nothing but the two ids, so the shape is composed here from the
 * shared branded-id primitives rather than added to the frozen schema layer.
 *
 * Must call (do not reimplement): can, restorePatch, getActor, toActionResult
 */

import { ActionNotFoundError, ForbiddenActionError } from "@/actions/_lib/action-errors";
import { withAction } from "@/actions/_lib/with-action";
import { CACHE_PROFILES, orgTag, projectTag, revalidateTagged } from "@/lib/cache";
import { can } from "@/lib/permissions";
import { restorePatch } from "@/lib/soft-delete";
import { orgIdSchema, projectIdSchema } from "@/schemas/common";
import { listProjects, restoreProject } from "@/server/services/project-service";
import type { ActionResult } from "@/types/api";
import type { Project } from "@/types/project";
import { z } from "zod";

const restoreProjectSchema = z.object({
  orgId: orgIdSchema,
  projectId: projectIdSchema,
});

type RestoreProjectInput = z.infer<typeof restoreProjectSchema>;

const run = withAction<typeof restoreProjectSchema, Project>(
  restoreProjectSchema,
  async (raw, actor) => {
    const input = raw as RestoreProjectInput;

    const page = await listProjects(actor, {
      orgId: input.orgId,
      limit: 100,
      includeArchived: true,
    });
    const current = page.items.find((row) => row.project.id === input.projectId);
    if (current === undefined) {
      throw new ActionNotFoundError(`project ${input.projectId}`);
    }

    const allowed = can(actor, "project:archive", {
      kind: "project",
      orgId: input.orgId,
      projectId: input.projectId,
      visibility: current.project.visibility,
      leadId: current.project.leadId,
    });
    if (!allowed) {
      throw new ForbiddenActionError("project:archive");
    }

    const project = await restoreProject(actor, input.orgId, input.projectId);

    // `restorePatch()` is the single definition of what "restored" looks like;
    // comparing against it catches a service that forgot to clear the column.
    const expected = restorePatch();
    if (project.archivedAt !== expected.archivedAt) {
      throw new ActionNotFoundError(`live project ${input.projectId}`);
    }

    revalidateTagged(
      [orgTag(input.orgId), projectTag(project.id)],
      CACHE_PROFILES.minutes,
    );
    return project;
  },
  { revalidate: ["projects"], cacheProfile: "minutes" },
);

export async function restoreProjectAction(raw: unknown): Promise<ActionResult<Project>> {
  return run(raw);
}
"use server";

/**
 * Updates project metadata.
 *
 * Owner D. Visibility is part of this payload, which is why the permission
 * resource carries the *incoming* visibility: raising a project to `public`
 * must be judged against what it is becoming, not what it was.
 *
 * Must call (do not reimplement): updateProjectSchema, can, getActor,
 * toActionResult
 */

import { ForbiddenActionError } from "@/actions/_lib/action-errors";
import { withAction } from "@/actions/_lib/with-action";
import { CACHE_PROFILES, projectTag, revalidateTagged } from "@/lib/cache";
import { can } from "@/lib/permissions";
import { updateProjectSchema, type UpdateProjectInput } from "@/schemas/project";
import { updateProject } from "@/server/services/project-service";
import type { ActionResult } from "@/types/api";
import type { Project } from "@/types/project";

const run = withAction<typeof updateProjectSchema, Project>(
  updateProjectSchema,
  async (raw, actor) => {
    const input = raw as UpdateProjectInput;

    const allowed = can(actor, "project:update", {
      kind: "project",
      orgId: input.orgId,
      projectId: input.projectId,
      visibility: input.visibility ?? "org",
      leadId: input.leadId ?? actor.userId,
    });
    if (!allowed) {
      throw new ForbiddenActionError("project:update");
    }

    const project = await updateProject(actor, input);
    revalidateTagged([projectTag(project.id)], CACHE_PROFILES.minutes);
    return project;
  },
  { revalidate: ["projects"], cacheProfile: "minutes" },
);

export async function updateProjectAction(raw: unknown): Promise<ActionResult<Project>> {
  return run(raw);
}

