      color: defaultValues?.color ?? "#6366f1",
      targetDate: defaultValues?.targetDate ?? null,
    });

    if (!parsed.success) {
      setInvalid(parsed.error.issues[0]?.message ?? "Check the form");
      return;
    }
    setInvalid(null);
    await submit(parsed.data);
  }

  const leadOptions: readonly SelectOption[] = [
    { value: "", label: "No lead" },
    ...members.map((member) => ({
      value: member.userId,
      label: member.user.name,
    })),
  ];

  return (
    <div className="project-form space-y-4">
      <FormField name="name" label="Name" required>
        <Input
          name="name"
          value={name}
          placeholder="Payments platform"
          onChange={setName}
        />
      </FormField>

      <FormField
        name="slug"
        label="URL slug"
        hint={slug.length > 0 ? `/projects/${slug}` : "Derived from the name"}
        error={reserved ? `"${slug}" is reserved` : null}
      >
        <Input
          name="slug"
          value={slugOverride}
          placeholder={slugify(name)}
          invalid={reserved}
          onChange={setSlugOverride}
        />
      </FormField>

      <FormField name="description" label="Description">
        <Textarea
          name="description"
          rows={3}
          value={description}
          onChange={setDescription}
        />
      </FormField>

      <FormField name="visibility" label="Visibility">
        <Select
          name="visibility"
          value={visibility}
          options={VISIBILITY_OPTIONS}
          onChange={(value) => setVisibility(value as ProjectVisibility)}
        />
      </FormField>

      <FormField name="leadId" label="Project lead">
        <Select
          name="leadId"
          value={leadId ?? ""}
          options={leadOptions}
          onChange={(value) =>
            setLeadId(value.length === 0 ? null : (value as UserId))
          }
      <div className="max-w-lg space-y-4">
        <h1 className="text-xl font-semibold tracking-tight">
          Project limit reached
        </h1>
        <p className="text-sm text-slate-600">
          The {org.plan} plan allows {limits.projects} projects and{" "}
          {summary.usage.projectsUsed} are in use. Archive one you have finished
          with, or upgrade the plan.
        </p>
        <div className="flex gap-4 text-sm">
          <Link href={`/${orgSlug}/projects`} className="text-slate-600">
            Back to projects
          </Link>
          <Link href={`/${orgSlug}/settings/billing`} className="text-indigo-600">
            See plans
          </Link>
        </div>
      </div>
    );
  }

  const suggestedName = typeof search.name === "string" ? search.name : "";
  const [members, suggestedSlug] = await Promise.all([
    listMembers(actor, { orgId: org.id, limit: MEMBER_PICKER_LIMIT }),
    suggestedName.length > 0
      ? suggestProjectSlug(org.id, suggestedName)
      : Promise.resolve(""),
  ]);

  return (
    <div className="max-w-lg space-y-8">
      <header>
        <h1 className="text-2xl font-semibold tracking-tight">New project</h1>
        <p className="mt-1 text-sm text-slate-600">
          {summary.usage.projectsUsed} of {limits.projects} projects used.
        </p>
      </header>

      <ProjectForm
        orgId={org.id}
        members={members.items}
        defaultValues={{
          orgId: org.id,
          name: suggestedName,
          slug: suggestedSlug,
          leadId: actor.userId,
        }}
        onSubmit={createProjectAction}
      />
    </div>
  );
}

