export const PROJECT_KEY_MAX_LENGTH = 4;

/**
 * Makes a project key unique against `taken` the way `uniqueSlug` does for
 * addresses: by appending `2`, `3`, … and trimming the base so the key never
 * grows past four characters.
 */
export function uniqueProjectKey(key: string, taken: Iterable<string>): string {
  const base = key.toUpperCase().slice(0, PROJECT_KEY_MAX_LENGTH);
  const used = new Set(Array.from(taken, (value) => value.toUpperCase()));
  if (!used.has(base)) return base;

  for (let suffix = 2; suffix < 1_000; suffix += 1) {
    const tail = String(suffix);
    const candidate = `${base.slice(0, PROJECT_KEY_MAX_LENGTH - tail.length)}${tail}`;
    if (!used.has(candidate)) return candidate;
  }
  throw new InvalidSlugError(base, "exhausted unique key suffixes");
}
EOF
