import { afterAll, beforeAll, describe, expect, it, vi } from "vitest";
vi.mock("@/lib/id", () => import("../server/_support/doubles/id"));
vi.mock("@/lib/logger", async () => (await import("../server/_support/doubles/misc")).loggerModule);
import { subscribe } from "@/lib/event-bus";
import { registerUsageListeners } from "@/server/services/usage-service";
import * as usageRepo from "@/server/repositories/usage-repository";
import * as projectRepo from "@/server/repositories/project-repository";
import * as issueService from "@/server/services/issue-service";
import * as projectService from "@/server/services/project-service";
import { createTenant, issueInput, useTemporaryDatabase } from "../server/_support/fixtures";
const pi = (orgId: any, name: string, slug: string, key = "") => ({ orgId, name, slug, key, description: null, visibility: "org" as const, leadId: null, color: "#6366f1", targetDate: null });
let cleanup: () => void;
beforeAll(async () => { cleanup = await useTemporaryDatabase(); });
afterAll(() => cleanup());
describe("scratch", () => {
  it("all", async () => {
    const off = registerUsageListeners();
    const t = await createTenant("scr", "free");
    await usageRepo.recomputeUsage(t.org.id);
    const a = await projectService.createProject(t.actors.member, pi(t.org.id, "Web Vendors", "web-vendors", "WV"));
    const b = await projectService.createProject(t.actors.admin, pi(t.org.id, "Web Visitors", "web-vendors", "WV")).catch(e => e);
    expect(String(b)).toMatch(/allows 2 projects/);
    await projectService.archiveProject(t.actors.admin, { orgId: t.org.id, projectId: a.id, archiveIssues: true });
    const c = await projectService.createProject(t.actors.member, pi(t.org.id, "Web Visitors", "web-vendors", "WV"));
    expect(c.key).toBe("WV2"); expect(c.slug).toBe("web-vendors-2");
    await expect(projectService.restoreProject(t.actors.admin, t.org.id, a.id)).rejects.toThrow(/allows 2/);
    await expect(projectService.restoreProject(t.actors.admin, t.org.id, c.id)).rejects.toThrow(/not archived/);
    await projectService.archiveProject(t.actors.admin, { orgId: t.org.id, projectId: c.id, archiveIssues: true });
    const r = await projectService.restoreProject(t.actors.admin, t.org.id, a.id);
    expect(r.slug).toBe("web-vendors");
    expect((await usageRepo.getUsage(t.org.id)).projectsUsed).toBe(2);
    expect((await usageRepo.recomputeUsage(t.org.id)).projectsUsed).toBe(2);
    const i = await issueService.createIssue(t.actors.member, issueInput(t.org.id, t.project.id));
    await expect(projectService.updateProject(t.actors.member, { orgId: t.org.id, projectId: t.project.id, status: "completed" })).rejects.toThrow(/open issue/);
    const p = await projectService.updateProject(t.actors.member, { orgId: t.org.id, projectId: t.project.id, status: "paused" });
    expect(p.status).toBe("paused");
    expect((await projectRepo.listProjects({ orgId: t.org.id, limit: 10, cursor: null, status: "paused" } as any)).items.map(x => x.id)).toEqual([t.project.id]);
    await expect(issueService.createIssue(t.actors.member, issueInput(t.org.id, t.project.id))).rejects.toThrow(/paused/);
    expect(i).toBeTruthy();
    off();
  });
});
EOF
